export type ProfileKind = 'customer' | 'order';

export interface ProfileRef {
  kind: ProfileKind;
  externalId: string;
}

/** The path `host.navigate` gets for "See full profile"; the adapter maps it to the dashboard route. */
export function profilePath(ref: ProfileRef): string {
  return `profile/${ref.kind}/${encodeURIComponent(ref.externalId)}`;
}

/** `total` is a decimal string such as "59.90" as the API sends money. */
export function formatMoney(
  total: number | string | undefined,
  currency: string | undefined
): string {
  if (total === undefined) return '';
  const amount = Number(total);
  if (!currency || Number.isNaN(amount)) return currency ? `${total} ${currency}` : String(total);
  try {
    return new Intl.NumberFormat(undefined, { style: 'currency', currency }).format(amount);
  } catch {
    return `${total} ${currency}`;
  }
}

export function formatDate(value: string | undefined): string {
  if (!value) return '';
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? value : date.toLocaleDateString();
}

/** `emailDomain` to "Email domain". */
export function humanize(key: string): string {
  const spaced = key
    .replace(/([A-Z])/g, ' $1')
    .toLowerCase()
    .trim();
  return spaced.charAt(0).toUpperCase() + spaced.slice(1);
}
