import { Button, Card } from '@socialscore/ui';
import type { ReactElement } from 'react';

import { useHost, useT } from '../hooks/usePlugin.js';

export interface ConnectScreenProps {
  /**
   * The adapter's connect URL: `GET /api/v2/stores/connect?platform=&shop=&redirect_uri=&state=`
   * with the adapter's own state and PKCE challenge already filled in.
   */
  connectUrl: string;
}

export function ConnectScreen({ connectUrl }: ConnectScreenProps): ReactElement {
  const host = useHost();
  const t = useT();
  return (
    <Card title={t('connect.title')} headingLevel={2}>
      <p className="ss-pc-text">{t(`connect.description.${host.platform}`)}</p>
      <Button variant="contained-primary" onClick={() => host.navigate(connectUrl)}>
        {t('connect.button')}
      </Button>
    </Card>
  );
}
