import type { PluginHost } from '../host.js';
import type {
  BatchResult,
  CheckResult,
  CheckSubject,
  CostEstimate,
  CustomerExport,
  CustomerInput,
  HookCreated,
  HookInput,
  OrderInput,
  Page,
  CheckedCustomer,
  Profile,
  RedactCustomerResult,
  RowId,
  SegmentSummary,
  StoreOverview,
  StoreSettingsResponse,
  TriggerSettings,
  UninstallResult,
} from '../types/index.js';

import { fromWire, toWire } from './case.js';
import { ApiError } from './errors.js';

/**
 * `external_id` to SocialScore id of the rows a batch stored. Keep it: an `order.created` event carries
 * our `order_id`, not the shop's order id.
 */
export function batchIdMap(ids: RowId[]): Map<string, number> {
  return new Map(ids.map((row) => [row.externalId, row.id]));
}

export function newIdempotencyKey(): string {
  const c = globalThis.crypto;
  if (c && typeof c.randomUUID === 'function') return c.randomUUID();
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}-${Math.random()
    .toString(36)
    .slice(2)}`;
}

async function readBody(response: Response): Promise<unknown> {
  const text = await response.text();
  if (!text) return undefined;
  try {
    return JSON.parse(text);
  } catch {
    return undefined;
  }
}

function errorFrom(response: Response, body: unknown): ApiError {
  const record = (body && typeof body === 'object' ? body : {}) as Record<string, unknown>;
  // The API answers either {code, message} or FastAPI's {detail: "code"} / {detail: {code, message}}.
  const detail =
    record.detail && typeof record.detail === 'object'
      ? (record.detail as Record<string, unknown>)
      : record;
  const code =
    typeof detail.code === 'string'
      ? detail.code
      : typeof record.detail === 'string'
        ? record.detail
        : undefined;
  const message = typeof detail.message === 'string' ? detail.message : undefined;
  const header = response.headers.get('Retry-After');
  const retryAfter = header !== null && /^\d+$/.test(header) ? Number(header) : undefined;
  return new ApiError(response.status, code, message, retryAfter);
}

/**
 * Typed calls against the public API v2 (design-public-api.md, design-events.md). Every request
 * goes through the injected host, which adds authentication. Responses are returned in camelCase.
 */
export class ApiClient {
  private readonly host: Pick<PluginHost, 'apiFetch'>;

  private readonly storePath: string;

  constructor(host: Pick<PluginHost, 'apiFetch'>, storeId: string | number) {
    this.host = host;
    this.storePath = `/api/v2/stores/${encodeURIComponent(String(storeId))}`;
  }

  private async request<T>(
    method: string,
    path: string,
    options: { body?: unknown; headers?: Record<string, string> } = {}
  ): Promise<T> {
    const headers: Record<string, string> = { Accept: 'application/json', ...options.headers };
    const init: RequestInit = { method, headers };
    if (options.body !== undefined) {
      headers['Content-Type'] = 'application/json';
      init.body = JSON.stringify(toWire(options.body));
    }
    const response = await this.host.apiFetch(path, init);
    const body = await readBody(response);
    if (!response.ok) throw errorFrom(response, body);
    return fromWire<T>(body);
  }

  // Store

  getSettings(): Promise<StoreSettingsResponse> {
    return this.request('GET', `${this.storePath}/settings`);
  }

  updateSettings(patch: Partial<TriggerSettings>): Promise<StoreSettingsResponse> {
    return this.request('PATCH', `${this.storePath}/settings`, { body: patch });
  }

  /** Only `every_account` has an estimate. `exploresMax` is an upper bound; nothing is run or charged. */
  getCostEstimate(): Promise<CostEstimate> {
    return this.request('GET', `${this.storePath}/settings/estimate?trigger=every_account`);
  }

  /**
   * The plugin was removed. The store stops being served; its key keeps the two redact routes for 7 days.
   * With `redact`, the store's customers, orders and the profiles its checks built are deleted now.
   */
  uninstall(options: { redact?: boolean } = {}): Promise<UninstallResult> {
    return this.request(
      'DELETE',
      options.redact ? `${this.storePath}?redact=true` : this.storePath
    );
  }

  // Data push (no charge, at most 500 rows per call)

  pushCustomers(customers: CustomerInput[]): Promise<BatchResult> {
    return this.request('POST', `${this.storePath}/customers:batch`, { body: { customers } });
  }

  pushOrders(orders: OrderInput[]): Promise<BatchResult> {
    return this.request('POST', `${this.storePath}/orders:batch`, { body: { orders } });
  }

  // Checks and profiles

  /**
   * Runs Check. Pass the same `idempotencyKey` when retrying the same click, so the store is not
   * charged twice; a fresh key is made when none is given.
   */
  runCheck(
    subject: CheckSubject,
    idempotencyKey: string = newIdempotencyKey()
  ): Promise<CheckResult> {
    const body =
      subject.orderExternalId !== undefined
        ? { orderExternalId: subject.orderExternalId }
        : { customerExternalId: subject.customerExternalId };
    return this.request('POST', `${this.storePath}/checks`, {
      body,
      headers: { 'Idempotency-Key': idempotencyKey },
    });
  }

  getCustomerProfile(externalId: string): Promise<Profile> {
    return this.request(
      'GET',
      `${this.storePath}/customers/${encodeURIComponent(externalId)}/profile`
    );
  }

  getOrderProfile(externalId: string): Promise<Profile> {
    return this.request(
      'GET',
      `${this.storePath}/orders/${encodeURIComponent(externalId)}/profile`
    );
  }

  // Dashboard reads. None of them charges or runs a check.

  getOverview(): Promise<StoreOverview> {
    return this.request('GET', `${this.storePath}/overview`);
  }

  listCheckedCustomers(page: number, pageSize: number): Promise<Page<CheckedCustomer>> {
    return this.request(
      'GET',
      `${this.storePath}/customers?checked=true&page=${page}&page_size=${pageSize}`
    );
  }

  /** Ready segments with a size band. A store key may read them; it never writes. */
  async listSegments(): Promise<SegmentSummary[]> {
    const body = await this.request<{ items: SegmentSummary[] }>('GET', '/api/v2/segments');
    return body.items;
  }

  // Privacy routes of one customer (Shopify customers/data_request and customers/redact, WordPress exporter and eraser).
  // The key of an uninstalled store may still redact for 7 days.

  /** What SocialScore holds for one customer. 404 `customer_not_found` when the store has none. */
  exportCustomer(externalId: string): Promise<CustomerExport> {
    return this.request(
      'GET',
      `${this.storePath}/customers/${encodeURIComponent(externalId)}/export`
    );
  }

  /** Redacts the customer and their orders. Safe to repeat: `customersRedacted` is 0 when nothing is left. */
  redactCustomer(externalId: string): Promise<RedactCustomerResult> {
    return this.request('DELETE', `${this.storePath}/customers/${encodeURIComponent(externalId)}`);
  }

  // Webhooks (REST hooks). Company keys only: /api/v2/hooks refuses a store key.

  createHook(input: HookInput): Promise<HookCreated> {
    return this.request('POST', '/api/v2/hooks', { body: input });
  }

  deleteHook(id: string | number): Promise<void> {
    return this.request('DELETE', `/api/v2/hooks/${encodeURIComponent(String(id))}`);
  }

  getHookSamples(eventType: string): Promise<unknown> {
    return this.request('GET', `/api/v2/hooks/samples/${encodeURIComponent(eventType)}`);
  }
}
