import { Badge, Button, Card, Checkbox, Spinner } from '@socialscore/ui';
import { useCallback, useEffect, useState } from 'react';
import type { ReactElement } from 'react';

import { ErrorNote } from '../components/ErrorNote.js';
import { useApi, useHost, useT } from '../hooks/usePlugin.js';
import { useResource } from '../hooks/useResource.js';
import type { CostEstimate, StoreStatus, TriggerKey, TriggerSettings } from '../types/index.js';

// The abandoned-cart trigger needs the Pixel (phase 5), so it is not offered yet.
const TRIGGERS: TriggerKey[] = [
  'onNewAccount',
  'everyAccount',
  'orderNewCustomer',
  'orderAnyCustomer',
  'manualOnly',
];

const STATUS_VARIANT = {
  active: 'success',
  disconnected: 'warning',
  uninstalled: 'error',
} as const;

/** Enrichment triggers of BRD 12.6 and the connect status. */
export function SettingsScreen(): ReactElement {
  const api = useApi();
  const host = useHost();
  const t = useT();
  const load = useCallback(() => api.getSettings(), [api]);
  const { data, error, loading, reload } = useResource(load);

  const [draft, setDraft] = useState<TriggerSettings>();
  const [saving, setSaving] = useState(false);
  const [saveError, setSaveError] = useState<unknown>();
  // "For every account" is only switched on after the merchant has seen the cost.
  const [costFor, setCostFor] = useState<'loading' | CostEstimate | 'failed'>();

  useEffect(() => {
    if (data) setDraft(data.settings);
  }, [data]);

  const askCost = () => {
    setCostFor('loading');
    api.getCostEstimate().then(setCostFor, () => setCostFor('failed'));
  };

  const toggle = (key: TriggerKey, on: boolean) => {
    if (!draft) return;
    if (key === 'everyAccount' && on) {
      askCost();
      return;
    }
    setDraft({ ...draft, [key]: on });
  };

  const save = async () => {
    if (!data || !draft) return;
    const patch: Partial<TriggerSettings> = {};
    TRIGGERS.forEach((key) => {
      if (draft[key] !== data.settings[key]) patch[key] = draft[key];
    });
    setSaving(true);
    setSaveError(undefined);
    try {
      await api.updateSettings(patch);
      host.toast(t('settings.saved'));
      reload();
    } catch (e) {
      setSaveError(e);
    } finally {
      setSaving(false);
    }
  };

  if (error !== undefined) return <ErrorNote error={error} onRetry={reload} />;
  if (!draft || !data) return loading ? <Spinner label={t('common.loading')} /> : <div />;

  const status: StoreStatus | undefined = data.status;
  const dirty = TRIGGERS.some((key) => draft[key] !== data.settings[key]);

  return (
    <Card title={t('settings.title')} headingLevel={2}>
      <p className="ss-pc-text">{t('settings.intro')}</p>
      {status && (
        <p className="ss-pc-status">
          <span>{t('settings.status')}: </span>
          <Badge variant={STATUS_VARIANT[status]}>{t(`settings.status.${status}`)}</Badge>
        </p>
      )}
      {status === 'disconnected' && <p className="ss-pc-text">{t('settings.disconnectedNote')}</p>}
      <fieldset className="ss-pc-triggers">
        <legend className="ss-visually-hidden">{t('settings.title')}</legend>
        {TRIGGERS.map((key) => (
          <Checkbox
            key={key}
            label={t(`settings.trigger.${key}`)}
            checked={draft[key]}
            onChange={(event) => toggle(key, event.target.checked)}
          />
        ))}
      </fieldset>
      {costFor && (
        <div className="ss-pc-cost" role="status">
          {costFor === 'loading' && <p>{t('settings.costLoading')}</p>}
          {costFor === 'failed' && <ErrorNote error={undefined} onRetry={askCost} />}
          {typeof costFor === 'object' && (
            <>
              <p>
                {t('settings.costPreview', {
                  count: costFor.exploresMax,
                  reused: costFor.reusedKnown,
                })}
              </p>
              <div className="ss-pc-actions">
                <Button
                  variant="contained-primary"
                  onClick={() => {
                    setDraft({ ...draft, everyAccount: true });
                    setCostFor(undefined);
                  }}
                >
                  {t('settings.costConfirm')}
                </Button>
                <Button variant="outlined-primary" onClick={() => setCostFor(undefined)}>
                  {t('common.cancel')}
                </Button>
              </div>
            </>
          )}
        </div>
      )}
      {saveError !== undefined && <ErrorNote error={saveError} />}
      <div className="ss-pc-actions">
        <Button variant="contained-primary" disabled={!dirty || saving} onClick={save}>
          {t('common.save')}
        </Button>
      </div>
    </Card>
  );
}
