import { Button } from '@socialscore/ui';
import type { ReactElement } from 'react';

import { useErrorText } from '../hooks/useErrorText.js';
import { useT } from '../hooks/usePlugin.js';

export interface ErrorNoteProps {
  error: unknown;
  onRetry?: () => void;
}

export function ErrorNote({ error, onRetry }: ErrorNoteProps): ReactElement {
  const t = useT();
  const text = useErrorText()(error);
  return (
    <div role="alert" className="ss-pc-error">
      <p className="ss-pc-error-text">{text}</p>
      {onRetry && (
        <Button variant="outlined-primary" onClick={onRetry}>
          {t('common.retry')}
        </Button>
      )}
    </div>
  );
}
